# Double-checking the original positions and building the grid correctly

bg = 8
block_val = 9
obj_val = 7

input_grid = [[bg]*20 for _ in range(14)]
for r in [4, 5]:
    for c in [5, 6]:
        input_grid[r][c] = block_val

for r, c, val in [(6, 4, obj_val), (7, 1, obj_val), (9, 2, obj_val)]:
    input_grid[r][c] = val

print("Input grid:")
for row in input_grid:
    print(row)

# Find all non-bg cells
non_bg = []
for r in range(14):
    for c in range(20):
        if input_grid[r][c] != bg:
            non_bg.append((r, c, input_grid[r][c]))

print("\nNon-background cells:")
for cell in non_bg:
    print(cell)

# Build output by reflecting each object point across the center of the 9-block
center_r, center_c = 4.5, 5.5

output_grid = [row[:] for row in input_grid]

for r, c, val in non_bg:
    if val == block_val:
        continue  # keep block as-is
    # Keep original
    output_grid[r][c] = val
    # Add reflection
    nr, nc = round(center_r * 2 - r), round(center_c * 2 - c)
    if 0 <= nr < 14 and 0 <= nc < 20:
        output_grid[nr][nc] = val

print("\nOutput grid:")
for row in output_grid:
    print(row)
